// Demonstração ISOLADA do Portal do Cliente (ferramenta de marketing).
// Página única, autocontida, SEM back-end e SEM pagamento — servida pública em /demo.
export const DEMO_CLIENTE_HTML = "<!doctype html>\n<html lang=\"pt-BR\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Ecobraz — Portal do Cliente (Demonstração)</title>\n<style>\n:root{\n  --green:#7ac943; --green2:#31a354; --green3:#15803d; --emerald:#059669;\n  --forest:#0f3324; --forest2:#0b2419;\n  --navy:#0b2136; --ink:#12314a; --muted:#5b7186; --line:#e6edf2;\n  --panel:#ffffff; --soft:#f4f8f5; --soft2:#eef3f1;\n  --gold:#f4b93e;\n  --ok:#22c55e; --okbg:#dcfce7; --oktx:#166534;\n  --warn:#eab308; --warnbg:#fef9c3; --warntx:#854d0e;\n  --blue:#2563eb; --bluebg:#e0edff; --bluetx:#1e40af;\n  --violet:#7c3aed; --violetbg:#ede9fe; --violettx:#5b21b6;\n  --radius:14px; --shadow:0 10px 26px rgba(11,33,54,.07); --shadow2:0 24px 60px rgba(6,18,13,.28);\n}\n*{box-sizing:border-box}\nhtml,body{margin:0;padding:0;background:var(--soft2);color:var(--ink);\n  font-family:-apple-system,BlinkMacSystemFont,\"Segoe UI\",Roboto,Helvetica,Arial,sans-serif;\n  -webkit-font-smoothing:antialiased}\nbutton{font-family:inherit;cursor:pointer}\nimg{max-width:100%}\n.mono{font-variant-numeric:tabular-nums}\n\n/* demo badge */\n.demoflag{position:fixed;top:12px;right:14px;z-index:200;background:#111c16;color:#eafaef;\n  border:1px solid rgba(122,201,67,.5);border-radius:999px;padding:7px 14px;font-size:12px;font-weight:800;\n  display:flex;align-items:center;gap:8px;box-shadow:0 6px 18px rgba(0,0,0,.25)}\n.demoflag .d{width:8px;height:8px;border-radius:50%;background:var(--gold);box-shadow:0 0 0 0 rgba(244,185,62,.6);animation:pulse 1.8s infinite}\n@keyframes pulse{0%{box-shadow:0 0 0 0 rgba(244,185,62,.5)}100%{box-shadow:0 0 0 10px rgba(244,185,62,0)}}\n@media (prefers-reduced-motion: reduce){.demoflag .d{animation:none}}\n\n/* ============ LOGIN ============ */\n#login{position:fixed;inset:0;z-index:150;display:flex;align-items:center;justify-content:center;\n  background:radial-gradient(1200px 700px at 80% -10%, rgba(122,201,67,.16), transparent 60%),\n   radial-gradient(900px 600px at 5% 110%, rgba(5,150,105,.16), transparent 60%),\n   linear-gradient(160deg,#06120d,#0a1f16 55%,#0d2b1e)}\n.login-card{width:380px;max-width:92vw;background:#fff;border-radius:18px;padding:30px;box-shadow:var(--shadow2)}\n.login-card .l{height:38px;margin-bottom:12px}\n.login-card h1{font-size:20px;color:var(--navy);margin:6px 0 3px}\n.login-card .sub{font-size:13px;color:var(--muted);margin-bottom:18px}\n.field{border:1px solid #dbe3ea;border-radius:10px;padding:12px 13px;font-size:14px;color:#334;margin-bottom:11px;\n  display:flex;align-items:center;gap:9px;background:#fbfdfe}\n.field span{color:var(--muted)}\n.field input{border:none;outline:none;background:transparent;font-size:14px;color:#213;width:100%}\n.btn{background:linear-gradient(90deg,var(--green2),var(--emerald));color:#fff;border:none;border-radius:10px;\n  padding:13px;font-size:15px;font-weight:800;width:100%;box-shadow:0 8px 18px rgba(5,150,105,.28)}\n.btn:active{transform:translateY(1px)}\n.secure{margin-top:14px;font-size:12px;color:var(--green3);display:flex;align-items:center;gap:7px;justify-content:center;font-weight:600}\n.login-demo{margin-top:16px;background:#f4f8f5;border:1px dashed #b6c9bd;border-radius:10px;padding:10px 12px;font-size:11.5px;color:#4a6a57;text-align:center}\n\n/* ============ APP SHELL ============ */\n#app{display:none;min-height:100vh}\n#app.on{display:grid;grid-template-columns:236px 1fr}\n.side{background:linear-gradient(180deg,var(--forest),var(--forest2));color:#dff3e4;padding:16px 12px;\n  display:flex;flex-direction:column;gap:3px;position:sticky;top:0;height:100vh;overflow:auto}\n.side .brand{height:30px;margin:6px 6px 16px}\n.nav{display:flex;align-items:center;gap:11px;padding:10px 12px;border-radius:10px;font-size:13.5px;color:#bfe6c8;\n  border:none;background:transparent;width:100%;text-align:left}\n.nav .ic{width:20px;text-align:center;font-size:15px}\n.nav:hover{background:rgba(255,255,255,.06);color:#fff}\n.nav.active{background:rgba(122,201,67,.18);color:#fff;font-weight:700}\n.side .spacer{flex:1}\n.side .cli{font-size:11px;color:#8fc7a0;padding:10px 12px;line-height:1.5;border-top:1px solid rgba(255,255,255,.08);margin-top:8px}\n.side .reset{margin-top:8px;background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.12);color:#cfe9d6;\n  border-radius:9px;padding:9px;font-size:12px;font-weight:700}\n.side .reset:hover{background:rgba(255,255,255,.12)}\n\n.main{min-width:0;display:flex;flex-direction:column}\n.top{height:60px;background:#fff;border-bottom:1px solid var(--line);display:flex;align-items:center;padding:0 26px;gap:14px;position:sticky;top:0;z-index:40}\n.top h1{font-size:17px;font-weight:800;color:var(--navy);letter-spacing:-.2px}\n.top .who{margin-left:auto;display:flex;align-items:center;gap:10px;font-size:12.5px;color:var(--muted)}\n.avatar{width:32px;height:32px;border-radius:50%;background:linear-gradient(135deg,var(--green),var(--emerald));\n  display:flex;align-items:center;justify-content:center;font-weight:800;font-size:12px;color:#08351f}\n.content{padding:24px 26px;max-width:1200px;width:100%}\n\n/* cards / primitives */\n.grid{display:grid;gap:16px}\n.k4{grid-template-columns:repeat(4,1fr)}\n.k3{grid-template-columns:repeat(3,1fr)}\n.k2{grid-template-columns:repeat(2,1fr)}\n.card{background:#fff;border:1px solid var(--line);border-radius:var(--radius);box-shadow:var(--shadow)}\n.pad{padding:18px}\n.kpi{position:relative;overflow:hidden;padding:18px}\n.kpi .accent{position:absolute;left:0;top:0;bottom:0;width:5px;background:linear-gradient(180deg,var(--green),var(--emerald))}\n.kpi .ic{position:absolute;right:14px;top:12px;font-size:22px;opacity:.22}\n.kpi .lab{font-size:12.5px;color:var(--muted);font-weight:600}\n.kpi .val{font-size:32px;font-weight:900;color:var(--navy);letter-spacing:-1px;margin-top:8px;line-height:1}\n.kpi .val small{font-size:15px;font-weight:800;color:var(--muted)}\n.kpi .foot{font-size:11.5px;color:var(--green3);margin-top:8px;font-weight:700}\n.esg{margin-top:16px;background:linear-gradient(90deg,var(--forest),#12503a);border-radius:var(--radius);\n  padding:18px 22px;color:#eafaef;display:flex;align-items:center;gap:16px;flex-wrap:wrap}\n.esg .big{font-size:20px;font-weight:900}.esg .em{color:var(--green)}\n.esg .badge{margin-left:auto;background:rgba(122,201,67,.16);border:1px solid rgba(122,201,67,.4);border-radius:12px;\n  padding:10px 16px;font-size:12.5px;font-weight:700;color:#fff}\n\n.sechead{display:flex;align-items:center;gap:12px;margin:2px 0 16px}\n.sechead h2{font-size:16px;color:var(--navy);font-weight:800;margin:0}\n.sechead .hint{font-size:12.5px;color:var(--muted)}\n.spread{margin-left:auto}\n\n/* pills / chips */\n.pill{font-size:10.5px;font-weight:800;padding:3px 9px;border-radius:999px;display:inline-block;white-space:nowrap}\n.p-ok{background:var(--okbg);color:var(--oktx)} .p-warn{background:var(--warnbg);color:var(--warntx)}\n.p-doc{background:var(--bluebg);color:var(--bluetx)} .p-esg{background:var(--violetbg);color:var(--violettx)}\n.p-cdf{background:#fdeecd;color:#7a4d00}\n.chip{background:#fff;border:1px solid #d9e2ea;border-radius:999px;padding:8px 14px;font-size:12.5px;color:#475569;font-weight:600}\n.chip.sel{background:var(--green2);border-color:var(--green2);color:#fff;box-shadow:0 6px 14px rgba(5,150,105,.25)}\n.chip:hover{border-color:var(--green2)}\n\n/* kanban */\n.kan{display:grid;grid-template-columns:repeat(5,1fr);gap:12px;align-items:start}\n.col{background:#fff;border:1px solid var(--line);border-radius:var(--radius);padding:10px;box-shadow:var(--shadow);min-height:120px}\n.col h5{font-size:12px;font-weight:800;color:var(--navy);display:flex;align-items:center;gap:6px;padding:2px 2px 8px;border-bottom:2px solid #eef2f4;margin:0 0 8px}\n.col h5 .n{margin-left:auto;background:#eef4f0;color:#3f6b53;border-radius:999px;font-size:11px;padding:1px 8px}\n.kc{background:#fbfdfe;border:1px solid #e8eef3;border-left:4px solid var(--green2);border-radius:10px;padding:9px 10px;\n  box-shadow:0 3px 8px rgba(11,33,54,.05);margin-bottom:9px;width:100%;text-align:left;display:block}\n.kc:hover{border-color:var(--green2);box-shadow:0 8px 18px rgba(5,150,105,.16);transform:translateY(-1px)}\n.kc .os{font-size:12px;font-weight:800;color:var(--navy)}\n.kc .cli{font-size:11px;color:var(--muted);margin-top:2px}\n.kc .mt{margin-top:7px;display:flex;align-items:center;gap:6px;font-size:10.5px;color:#5b7186}\n.kc.new{animation:pop .6s}\n@keyframes pop{0%{transform:scale(.9);box-shadow:0 0 0 3px rgba(122,201,67,.4)}100%{transform:none}}\n\n/* list rows */\n.rowlist{overflow:hidden;border-radius:var(--radius)}\n.row{display:flex;align-items:center;gap:14px;padding:13px 16px;border-bottom:1px solid #eef2f4;background:#fff}\n.row:last-child{border-bottom:none}\n.row .ic{width:38px;height:38px;border-radius:10px;display:flex;align-items:center;justify-content:center;font-size:17px;background:var(--soft);flex:none}\n.row .nm{font-weight:700;color:var(--navy);font-size:13.5px}\n.row .meta{font-size:11.5px;color:var(--muted);margin-top:2px}\n.dl{margin-left:auto;background:var(--soft);border:1px solid var(--line);border-radius:9px;padding:8px 13px;font-size:12px;font-weight:800;color:var(--green3);display:flex;align-items:center;gap:6px}\n.dl:hover{background:#e8f3ec;border-color:var(--green2)}\n.btn2{background:linear-gradient(90deg,var(--green2),var(--emerald));color:#fff;border:none;border-radius:9px;padding:9px 15px;font-size:12.5px;font-weight:800}\n.btn2:hover{filter:brightness(1.04)} .btn2:active{transform:translateY(1px)}\n.btn-ghost{background:#fff;border:1px solid var(--line);border-radius:9px;padding:9px 15px;font-size:12.5px;font-weight:800;color:var(--navy)}\n.btn-ghost:hover{border-color:var(--green2);color:var(--green3)}\n\n/* form */\n.form label{display:block;font-size:12.5px;color:var(--navy);font-weight:700;margin:14px 0 6px}\n.form input,.form select,.form textarea{width:100%;border:1px solid #dbe3ea;border-radius:10px;padding:11px 13px;font-size:14px;color:#213;background:#fbfdfe;outline:none;font-family:inherit}\n.form input:focus,.form select:focus,.form textarea:focus{border-color:var(--green2);box-shadow:0 0 0 3px rgba(122,201,67,.15)}\n\n/* timeline */\n.tl .step{display:flex;gap:14px;position:relative;padding-bottom:16px}\n.tl .step:not(:last-child):before{content:\"\";position:absolute;left:13px;top:26px;bottom:-2px;width:2px;background:#e2ebe5}\n.tl .nd{width:28px;height:28px;border-radius:50%;flex:none;display:flex;align-items:center;justify-content:center;font-size:13px;color:#fff;background:var(--green2);box-shadow:0 0 0 4px #e6f6ec;z-index:2}\n.tl .step.future .nd{background:#cbd5e1;box-shadow:0 0 0 4px #eef2f6}\n.tl .tt{font-weight:800;color:var(--navy);font-size:13.5px}\n.tl .dts{font-size:11.5px;color:var(--muted);margin-top:3px;display:flex;gap:16px;flex-wrap:wrap}\n.tl .dts .rz{color:var(--green3);font-weight:700}\n.b{font-size:10px;font-weight:800;padding:2px 8px;border-radius:999px;margin-left:8px}\n\n/* carbon bars */\n.bar{display:flex;align-items:center;gap:12px;margin:11px 0}\n.bar .lb{width:92px;font-size:12.5px;color:#475569;text-align:right}\n.bar .track{flex:1;height:22px;background:#eef3f1;border-radius:6px;overflow:hidden}\n.bar .fill{height:100%;border-radius:6px;background:linear-gradient(90deg,var(--green),var(--emerald));transition:width 1s cubic-bezier(.3,.8,.3,1)}\n.bar .vl{width:56px;font-size:12.5px;font-weight:800;color:var(--navy);text-align:right}\n\n/* modal */\n.overlay{position:fixed;inset:0;z-index:120;background:rgba(6,18,13,.5);display:none;align-items:center;justify-content:center;padding:20px}\n.overlay.on{display:flex}\n.modal{background:#fff;border-radius:16px;box-shadow:var(--shadow2);max-width:760px;width:100%;max-height:88vh;overflow:auto}\n.modal .mh{display:flex;align-items:center;gap:12px;padding:16px 20px;border-bottom:1px solid var(--line);position:sticky;top:0;background:#fff;z-index:2}\n.modal .mh h3{font-size:16px;color:var(--navy);margin:0;font-weight:800}\n.modal .x{margin-left:auto;background:var(--soft);border:1px solid var(--line);border-radius:8px;width:32px;height:32px;font-size:16px;color:#556}\n.modal .x:hover{background:#e8eef3}\n.modal .mb{padding:20px}\n\n/* certificate (doc preview) */\n.cert{border:1px solid var(--line);border-radius:14px;overflow:hidden}\n.cert .ch{background:linear-gradient(120deg,var(--forest),#12503a);color:#eafaef;padding:14px 20px;display:flex;align-items:center;gap:12px}\n.cert .ch img{height:24px}\n.cert .ch .t{margin-left:auto;text-align:right}\n.cert .ch .t b{font-size:14px;display:block}.cert .ch .t span{font-size:11px;color:#bfe6c8}\n.cert .cb{padding:18px 20px;position:relative}\n.cert h4{font-size:17px;color:var(--navy);margin:0 0 10px}\n.cert .r{display:flex;justify-content:space-between;gap:14px;font-size:12.5px;padding:7px 0;border-bottom:1px dashed #e6edf2;padding-right:140px}\n.cert .r b{color:var(--navy);text-align:right}\n.cert .scan{position:absolute;right:20px;bottom:16px;width:110px;height:110px;border:1px solid #e6edf2;border-radius:12px;padding:7px;background:#fff}\n.cert .scan img{width:100%;display:block;image-rendering:pixelated}\n.stamp{display:inline-block;border:3px solid var(--green2);color:var(--green3);border-radius:12px;padding:6px 12px;font-weight:900;transform:rotate(-6deg);margin-top:8px;line-height:1.1}\n.stamp small{display:block;font-size:9.5px;font-weight:700;color:var(--green2)}\n\n/* toast */\n#toasts{position:fixed;left:50%;bottom:26px;transform:translateX(-50%);z-index:300;display:flex;flex-direction:column;gap:10px;align-items:center}\n.toast{background:#111c16;color:#eafaef;border:1px solid rgba(122,201,67,.4);border-radius:12px;padding:12px 18px;font-size:13.5px;\n  box-shadow:0 12px 30px rgba(0,0,0,.3);display:flex;align-items:center;gap:10px;animation:tin .3s}\n.toast .ck{color:var(--green)}\n@keyframes tin{from{opacity:0;transform:translateY(10px)}to{opacity:1}}\n\n.note{font-size:12px;color:var(--muted);display:flex;align-items:center;gap:8px;margin-top:14px}\n.hollow{background:var(--soft);border:1px dashed #c5d3ca;border-radius:12px;padding:16px;font-size:13px;color:#4a6a57}\nh3.blk{font-size:15px;color:var(--navy);margin:0 0 12px}\n.mut{color:var(--muted)}\n\n/* tabs (dentro do detalhe da OS) */\n.tabs{display:flex;gap:4px;border-bottom:1px solid var(--line);margin:0 0 16px;flex-wrap:wrap}\n.tab{background:transparent;border:none;border-bottom:2px solid transparent;padding:10px 14px;font-size:13px;font-weight:700;color:var(--muted)}\n.tab.sel{color:var(--green3);border-bottom-color:var(--green2)}\n.tab:hover{color:var(--navy)}\n\n/* galeria de fotos georreferenciadas */\n.gallery{display:grid;grid-template-columns:repeat(auto-fill,minmax(210px,1fr));gap:14px}\n.photo2{position:relative;border-radius:12px;overflow:hidden;border:1px solid var(--line);box-shadow:var(--shadow);cursor:pointer;aspect-ratio:4/3;background:linear-gradient(135deg,#c3d2cb,#9ab0a6)}\n.photo2 .eqbg{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;font-size:60px;opacity:.55}\n.photo2 .etapabadge{position:absolute;top:8px;left:8px;background:rgba(15,51,36,.92);color:#eafaef;font-size:10px;font-weight:800;padding:4px 9px;border-radius:999px;z-index:2;letter-spacing:.3px}\n.photo2 .rec{position:absolute;top:9px;right:10px;z-index:2;color:#fff;font-size:10px;font-weight:800;display:flex;align-items:center;gap:4px;text-shadow:0 1px 2px rgba(0,0,0,.5)}\n.photo2 .rec i{width:8px;height:8px;border-radius:50%;background:#ef4444;display:inline-block}\n.photo2 .geostamp{position:absolute;left:0;right:0;bottom:0;background:linear-gradient(0deg,rgba(0,0,0,.78),transparent);color:#eafaef;padding:20px 10px 8px;font-size:9.5px;font-family:'Courier New',monospace;line-height:1.45;z-index:2}\n.photo2 .geostamp b{color:#8ff0b0}\n.photo2:hover{transform:translateY(-2px);box-shadow:0 14px 26px rgba(11,33,54,.16)}\n\n/* mini-mapa estilizado (geo) */\n.smap{position:relative;height:230px;border-radius:12px;overflow:hidden;border:1px solid var(--line);\n  background:repeating-linear-gradient(90deg,#e7edef 0 2px,transparent 2px 58px),repeating-linear-gradient(0deg,#e7edef 0 2px,transparent 2px 58px),#eef3f1}\n.smap .road{position:absolute;background:#d7e0e4;border-radius:3px}\n.smap .pin{position:absolute;font-size:30px;transform:translate(-50%,-100%);z-index:3;filter:drop-shadow(0 3px 3px rgba(0,0,0,.3))}\n.smap .halo{position:absolute;width:18px;height:18px;border-radius:50%;background:rgba(5,150,105,.35);transform:translate(-50%,-50%);z-index:2;animation:halo 1.8s ease-out infinite}\n@keyframes halo{0%{box-shadow:0 0 0 0 rgba(5,150,105,.5)}100%{box-shadow:0 0 0 22px rgba(5,150,105,0)}}\n@media (prefers-reduced-motion:reduce){.smap .halo{animation:none}}\n.metarow{display:flex;justify-content:space-between;gap:12px;font-size:12.5px;padding:7px 0;border-bottom:1px dashed #e6edf2}\n.metarow span{color:var(--muted)} .metarow b{color:var(--navy);font-family:'Courier New',monospace}\n\n/* relatórios */\n.report{border:1px solid var(--line);border-radius:12px;overflow:hidden}\n.report .rh{background:linear-gradient(120deg,var(--forest),#12503a);color:#eafaef;padding:15px 20px;display:flex;align-items:center;gap:12px}\n.report .rh img{height:22px}\n.report .rh .t{margin-left:auto;text-align:right;font-size:11px;color:#bfe6c8}\n.report .rb{padding:18px 20px}\n.report h4{margin:0 0 10px;color:var(--navy);font-size:16px}\n.repkpi{display:grid;grid-template-columns:repeat(auto-fit,minmax(120px,1fr));gap:12px;margin:4px 0 16px}\n.repkpi .c{background:var(--soft);border:1px solid var(--line);border-radius:10px;padding:12px;text-align:center}\n.repkpi .n{font-size:22px;font-weight:900;color:var(--navy)}\n.repkpi .l{font-size:11px;color:var(--muted);margin-top:3px;line-height:1.3}\n.tbl{width:100%;border-collapse:collapse;font-size:12.5px}\n.tbl th{text-align:left;color:var(--muted);font-weight:700;padding:8px 10px;border-bottom:2px solid var(--line);font-size:11.5px}\n.tbl td{padding:9px 10px;border-bottom:1px solid #eef2f4;color:var(--ink)}\n.tbl tr:last-child td{border-bottom:none}\n.tbl .r{text-align:right;font-variant-numeric:tabular-nums}\n\n/* cadeia de custódia (rastreabilidade rica) */\n.cchain .cs{display:flex;gap:14px;padding-bottom:14px;position:relative}\n.cchain .cs:not(:last-child):before{content:\"\";position:absolute;left:19px;top:44px;bottom:-2px;width:2px;background:#dbe7e0}\n.cchain .cn{width:40px;height:40px;border-radius:11px;flex:none;display:flex;align-items:center;justify-content:center;font-size:19px;background:#eafaef;border:1px solid #cdecd7;z-index:2}\n.cchain .cs.fut .cn{background:#eef2f6;border-color:#e2e8f0;filter:grayscale(1);opacity:.7}\n.cchain .cc{flex:1;background:#fff;border:1px solid var(--line);border-radius:12px;padding:12px 14px;box-shadow:var(--shadow)}\n.cchain .cc h4{margin:0;font-size:14px;color:var(--navy);display:flex;align-items:center;gap:8px}\n.cchain .cc .meta{font-size:11.5px;color:var(--muted);margin-top:4px;line-height:1.5}\n.cchain .cc .meta b{color:var(--ink);font-weight:700}\n.cchain .cc .tags{margin-top:9px;display:flex;gap:6px;flex-wrap:wrap}\n.miniphoto{width:40px;height:32px;border-radius:6px;background:linear-gradient(135deg,#c3d2cb,#9ab0a6);display:inline-flex;align-items:center;justify-content:center;font-size:15px;border:1px solid #cde;cursor:pointer;position:relative}\n.tagdoc{font-size:10px;font-weight:800;padding:3px 8px;border-radius:999px;cursor:pointer;border:1px solid transparent}\n.tagdoc:hover{filter:brightness(.97)}\n\n/* sparkline / barras no painel */\n.sparkrow{display:flex;align-items:flex-end;gap:5px;height:56px;margin-top:10px}\n.sparkrow .bar2{flex:1;background:linear-gradient(180deg,var(--green),var(--emerald));border-radius:4px 4px 0 0;min-height:6px}\n.donut{width:90px;height:90px;border-radius:50%;background:conic-gradient(var(--emerald) 0 92%, #e6efe9 92% 100%);display:flex;align-items:center;justify-content:center;flex:none}\n.donut .in{width:64px;height:64px;border-radius:50%;background:#fff;display:flex;align-items:center;justify-content:center;font-weight:900;color:var(--navy);font-size:16px}\n\n@media (max-width:900px){\n  #app.on{grid-template-columns:1fr}\n  .side{position:static;height:auto;flex-direction:row;flex-wrap:wrap;gap:4px}\n  .side .brand{width:100%}.side .spacer,.side .cli,.side .reset{display:none}\n  .k4,.k3{grid-template-columns:repeat(2,1fr)} .kan{grid-template-columns:1fr;}\n  .k2{grid-template-columns:1fr}\n}\n</style>\n</head>\n<body>\n\n<div class=\"demoflag\"><span class=\"d\"></span> MODO DEMONSTRAÇÃO</div>\n\n<!-- ============ LOGIN ============ -->\n<div id=\"login\">\n  <div class=\"login-card\">\n    <img class=\"l\" src=\"data:image/png;base64,\" alt=\"Ecobraz\">\n    <h1>Área do Cliente</h1>\n    <div class=\"sub\">Portal de Grandes Contas — acesso exclusivo por CNPJ.</div>\n    <div class=\"field\"><span>🏢</span><input id=\"in-emp\" value=\"Empresa Demonstração S.A.\" readonly></div>\n    <div class=\"field\"><span>✉️</span><input id=\"in-mail\" value=\"gestao.ambiental@empresa.com.br\"></div>\n    <button class=\"btn\" id=\"enter\">Entrar com link seguro</button>\n    <div class=\"secure\">🔒 Login sem senha — nada para vazar</div>\n    <div class=\"login-demo\">Esta é uma <b>demonstração</b>. Nenhum dado é real ou processado — explore à vontade: qualquer clique apenas simula a operação.</div>\n  </div>\n</div>\n\n<!-- ============ APP ============ -->\n<div id=\"app\">\n  <aside class=\"side\">\n    <img class=\"brand\" src=\"data:image/png;base64,\" alt=\"Ecobraz\">\n    <button class=\"nav\" data-nav=\"painel\"><span class=\"ic\">📊</span> Painel</button>\n    <button class=\"nav\" data-nav=\"kanban\"><span class=\"ic\">🗂️</span> Acompanhamento</button>\n    <button class=\"nav\" data-nav=\"rastreabilidade\"><span class=\"ic\">🔎</span> Rastreabilidade</button>\n    <button class=\"nav\" data-nav=\"evidencias\"><span class=\"ic\">📸</span> Evidências (fotos)</button>\n    <button class=\"nav\" data-nav=\"docs\"><span class=\"ic\">📑</span> Documentos</button>\n    <button class=\"nav\" data-nav=\"relatorios\"><span class=\"ic\">📈</span> Relatórios</button>\n    <button class=\"nav\" data-nav=\"nova\"><span class=\"ic\">➕</span> Nova solicitação</button>\n    <button class=\"nav\" data-nav=\"expressa\"><span class=\"ic\">⚡</span> Coleta Expressa</button>\n    <button class=\"nav\" data-nav=\"carbono\"><span class=\"ic\">🌍</span> Carbono &amp; ESG</button>\n    <button class=\"nav\" data-nav=\"seguranca\"><span class=\"ic\">🔒</span> Segurança</button>\n    <button class=\"nav\" data-nav=\"adote\"><span class=\"ic\">🤝</span> Adote um Bairro</button>\n    <button class=\"nav\" data-nav=\"atendimento\"><span class=\"ic\">💬</span> Atendimento</button>\n    <button class=\"nav\" data-nav=\"usuarios\"><span class=\"ic\">👥</span> Usuários</button>\n    <div class=\"spacer\"></div>\n    <div class=\"cli\">Empresa Demonstração S.A.<br>Acesso exclusivo por CNPJ</div>\n    <button class=\"reset\" id=\"reset\">↺ Reiniciar demonstração</button>\n  </aside>\n  <div class=\"main\">\n    <header class=\"top\"><h1 id=\"title\">Painel</h1>\n      <div class=\"who\"><span id=\"whorole\">Gestor Ambiental</span><div class=\"avatar\">PS</div></div>\n    </header>\n    <div class=\"content\" id=\"view\"></div>\n  </div>\n</div>\n\n<div class=\"overlay\" id=\"overlay\"><div class=\"modal\" id=\"modal\"></div></div>\n<div id=\"toasts\"></div>\n\n<script>\nconst QR=\"data:image/png;base64,\";\nconst $=s=>document.querySelector(s);\nconst money=n=>'R$ '+n.toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2});\nconst esc=s=>String(s).replace(/[&<>\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;'}[c]));\n\nconst COLS=[\n  {k:'aguardando', t:'📥 Aguardando coleta'},\n  {k:'transporte', t:'🚚 Em transporte'},\n  {k:'processamento', t:'🛠️ Em processamento'},\n  {k:'finalizado', t:'✅ Finalizado'},\n  {k:'concluido', t:'📑 Concluído + CDF'},\n];\nconst COLIDX={aguardando:0,transporte:1,processamento:2,finalizado:3,concluido:4};\n\nfunction seed(){return [\n  {id:'OS-2048',tipo:'Notebooks',qtd:'120 un.',col:'aguardando',tag:['p-warn','Agendado · 06/08'],valor:3200,pago:false,dados:true},\n  {id:'OS-2049',tipo:'Servidores',qtd:'8 un.',col:'aguardando',tag:['p-warn','Agendado · 07/08'],valor:1800,pago:false,dados:true},\n  {id:'OS-2041',tipo:'HDs + mídias',qtd:'340 un.',col:'transporte',tag:['p-ok','Recebido no galpão'],valor:2400,pago:true,dados:true},\n  {id:'OS-2035',tipo:'Desmonte + destruição',qtd:'210 kg',col:'processamento',tag:['p-doc','Descaracterização'],valor:1240,pago:false,dados:false},\n  {id:'OS-2036',tipo:'Trituração de mídias',qtd:'80 un.',col:'processamento',tag:['p-doc','LGPD'],valor:980,pago:true,dados:true},\n  {id:'OS-2030',tipo:'Monitores + CPUs',qtd:'260 kg',col:'finalizado',tag:['p-warn','Emitindo CDF'],valor:1500,pago:true,dados:false},\n  {id:'OS-2021',tipo:'Equip. de informática',qtd:'512 kg',col:'concluido',tag:['p-ok','CDF ✓'],valor:2100,pago:true,dados:true},\n];}\nlet OS=seed();\nlet seq=2050;\n\n/* ---------- documentos por estágio ---------- */\nfunction docsFor(o){\n  const i=COLIDX[o.col]; const d=[];\n  if(i>=1) d.push({t:'mtr', nm:'MTR de entrada', ic:'🚚', cls:'p-doc', lab:'MTR'});\n  if(i>=2 && o.dados) d.push({t:'lgpd', nm:'Laudo de Destruição de Dados (LGPD)', ic:'🔒', cls:'p-ok', lab:'LAUDO'});\n  if(i>=3) d.push({t:'desc', nm:'Laudo de Descaracterização', ic:'🛠️', cls:'p-ok', lab:'LAUDO'});\n  if(i>=3) d.push({t:'foto', nm:'Laudo Fotográfico', ic:'📷', cls:'p-ok', lab:'LAUDO'});\n  if(i>=4) d.push({t:'mtrs', nm:'MTR de saída', ic:'🚛', cls:'p-doc', lab:'MTR'});\n  if(i>=4) d.push({t:'cdf', nm:'CDF — Certificado de Destinação Final', ic:'🏅', cls:'p-cdf', lab:'CDF'});\n  return d;\n}\n\n/* ---------- timeline por estágio ---------- */\nfunction steps(o){\n  const i=COLIDX[o.col];\n  const base=[\n    ['Solicitação registrada','01/08','01/08'],\n    ['Coleta realizada','05/08', i>=1?'04/08':null],\n    ['Recebido e pesado no galpão','05/08', i>=1?'05/08':null],\n    ['Em processamento / desmonte','08/08', i>=2?'08/08':null],\n    ['Laudos técnicos','11/08', i>=3?'10/08':null],\n    ['CDF emitido e validado pelo RT','12/08', i>=4?'12/08':null],\n  ];\n  return base.map((s,idx)=>({tt:s[0],prev:s[1],real:s[2],done:idx<=i+ (o.col==='aguardando'?0:0)}));\n}\n\n/* ---------- fotos georreferenciadas (modelo) ---------- */\nconst PHOTOS=[\n {minI:1, etapa:'Coleta na origem', ic:'💻', gps:'-23.5613, -46.6560', addr:'Av. Paulista, 1000 — São Paulo/SP', dt:'04/08/2026 14:07:22', acc:'±4 m', resp:'Agente de coletas', x:16, y:74},\n {minI:1, etapa:'Recebimento na doca', ic:'📦', gps:'-23.4543, -46.5337', addr:'Galpão Ecobraz — Guarulhos/SP', dt:'05/08/2026 15:38:10', acc:'±3 m', resp:'Operação', x:80, y:30},\n {minI:1, etapa:'Pesagem na balança', ic:'⚖️', gps:'-23.4543, -46.5337', addr:'Galpão Ecobraz — Guarulhos/SP', dt:'05/08/2026 15:41:02', acc:'±3 m', resp:'Operação', x:80, y:30},\n {minI:2, etapa:'Triagem', ic:'🧰', gps:'-23.4544, -46.5338', addr:'Galpão Ecobraz — Guarulhos/SP', dt:'08/08/2026 09:12:44', acc:'±3 m', resp:'Operação', x:80, y:30},\n {minI:2, etapa:'Desmonte', ic:'🛠️', gps:'-23.4544, -46.5338', addr:'Galpão Ecobraz — Guarulhos/SP', dt:'08/08/2026 11:03:19', acc:'±3 m', resp:'Operação', x:80, y:30},\n {minI:2, dados:true, etapa:'Destruição de dados (LGPD)', ic:'🔒', gps:'-23.4545, -46.5339', addr:'Sala segura — Galpão Ecobraz', dt:'08/08/2026 14:20:57', acc:'±3 m', resp:'Eng. RT', x:80, y:30},\n {minI:3, etapa:'Descaracterização', ic:'🔨', gps:'-23.4545, -46.5339', addr:'Galpão Ecobraz — Guarulhos/SP', dt:'10/08/2026 10:05:00', acc:'±3 m', resp:'Eng. RT', x:80, y:30},\n {minI:4, etapa:'Destinação final', ic:'♻️', gps:'-23.4001, -46.7160', addr:'Recicladora homologada CETESB', dt:'12/08/2026 09:30:00', acc:'±4 m', resp:'Destino homologado', x:58, y:14},\n];\nfunction fotosFor(o){ const i=COLIDX[o.col]; return PHOTOS.filter(p=> i>=p.minI && (!p.dados || o.dados)); }\nfunction fotoCard(p,osId,idx){\n  return `<div class=\"photo2\" onclick=\"openFoto('${osId}',${idx})\">\n    <div class=\"eqbg\">${p.ic}</div><div class=\"etapabadge\">${esc(p.etapa)}</div><div class=\"rec\"><i></i>GEO</div>\n    <div class=\"geostamp\">📍 <b>${p.gps}</b> ${p.acc}<br>${esc(p.addr)}<br>🕒 ${p.dt}</div></div>`;\n}\nfunction smapHTML(x,y){\n  return `<div class=\"smap\">\n    <div class=\"road\" style=\"left:0;right:0;top:${y}%;height:6px;opacity:.7\"></div>\n    <div class=\"road\" style=\"top:0;bottom:0;left:${x}%;width:6px;opacity:.7\"></div>\n    <div class=\"halo\" style=\"left:${x}%;top:${y}%\"></div><div class=\"pin\" style=\"left:${x}%;top:${y}%\">📍</div></div>`;\n}\nwindow.openFoto=(osId,idx)=>{\n  const o=OS.find(x=>x.id===osId); if(!o)return; const p=fotosFor(o)[idx]; if(!p)return;\n  openModal(`<div class=\"mh\"><h3>Evidência fotográfica · ${esc(p.etapa)}</h3><button class=\"x\" onclick=\"closeModal()\">✕</button></div>\n   <div class=\"mb\">\n     <div class=\"photo2\" style=\"aspect-ratio:16/7;cursor:default;margin-bottom:14px\">\n       <div class=\"eqbg\" style=\"font-size:90px\">${p.ic}</div>\n       <div class=\"etapabadge\">${esc(p.etapa)} · ${o.id}</div><div class=\"rec\"><i></i>GEO-REF</div>\n       <div class=\"geostamp\" style=\"font-size:11px\">📍 <b>${p.gps}</b> (${p.acc})<br>${esc(p.addr)}<br>🕒 ${p.dt} · 👤 ${esc(p.resp)}</div></div>\n     <div class=\"grid k2\" style=\"gap:16px;align-items:start\">\n       <div>${smapHTML(p.x,p.y)}<div class=\"note\">📍 Local exato do registro, pelo GPS do dispositivo.</div></div>\n       <div class=\"card pad\">\n         <div class=\"metarow\"><span>Coordenadas</span><b>${p.gps}</b></div>\n         <div class=\"metarow\"><span>Precisão GPS</span><b>${p.acc}</b></div>\n         <div class=\"metarow\"><span>Endereço</span><b style=\"font-family:inherit\">${esc(p.addr)}</b></div>\n         <div class=\"metarow\"><span>Data / hora</span><b>${p.dt}</b></div>\n         <div class=\"metarow\"><span>Responsável</span><b style=\"font-family:inherit\">${esc(p.resp)}</b></div>\n         <div class=\"metarow\" style=\"border:none\"><span>OS</span><b style=\"font-family:inherit\">${o.id} · ${esc(o.tipo)}</b></div>\n       </div>\n     </div>\n     <div style=\"display:flex;gap:10px;margin-top:14px;align-items:center\"><button class=\"btn2\" onclick=\"toast('Foto original baixada (demo).','⬇')\">⬇ Baixar foto original</button>\n       <button class=\"btn-ghost\" onclick=\"toast('Metadados (EXIF/GPS) exportados (demo).','🧾')\">Exportar metadados</button>\n       <span class=\"note\" style=\"margin:0 0 0 auto\">Demonstração — imagem ilustrativa.</span></div>\n   </div>`);\n};\n\n/* ---------- cadeia de custódia (rastreabilidade) ---------- */\nconst DOCMETA={mtr:['p-doc','MTR'],mtrs:['p-doc','MTR'],lgpd:['p-ok','LAUDO'],desc:['p-ok','LAUDO'],foto:['p-ok','LAUDO'],cdf:['p-cdf','CDF'],esg:['p-esg','ESG'],rastr:['p-doc','RASTR'],dmr:['p-doc','DMR'],conf:['p-ok','CONF'],destino:['p-ok','DEST']};\nconst docCls=t=>(DOCMETA[t]||['p-doc'])[0];\nfunction chainFor(o){\n  const i=COLIDX[o.col];\n  return [\n   {done:true, ic:'📝', tt:'Solicitação registrada', quando:'01/08/2026', onde:'Portal do cliente', quem:'Gestor Ambiental (cliente)', oque:esc(o.tipo)+' · '+esc(o.qtd), docs:[], fotos:0},\n   {done:i>=1, ic:'💻', tt:'Coleta na origem', quando:'04/08/2026 14:07', onde:'Av. Paulista, 1000 — SP · GPS −23.5613, −46.6560', quem:'Agente de coletas', oque:'Foto georreferenciada + GPS + assinatura', docs:[{t:'mtr',lab:'MTR entrada'}], fotos:1},\n   {done:i>=1, ic:'⚖️', tt:'Recebimento e pesagem no galpão', quando:'05/08/2026 15:40', onde:'Galpão Ecobraz — Guarulhos/SP', quem:'Operação', oque:'Pesagem conferida na balança · NF-e amarrada à OS', docs:[], fotos:2},\n   {done:i>=2, ic:'🛠️', tt:'Triagem, desmonte'+(o.dados?' e destruição de dados':''), quando:'08/08/2026', onde:'Galpão Ecobraz'+(o.dados?' (sala segura p/ dados)':''), quem:'Operação'+(o.dados?' + Eng. RT':''), oque:'Descaracterização física'+(o.dados?' + destruição de dados (LGPD)':''), docs:o.dados?[{t:'lgpd',lab:'Laudo LGPD'}]:[], fotos:o.dados?3:2},\n   {done:i>=3, ic:'📋', tt:'Laudos técnicos emitidos', quando:'10/08/2026', onde:'Engenharia Ambiental', quem:'Eng. Marcelo Aragão · CREA 5062654748', oque:'Descaracterização · Fotográfico'+(o.dados?' · LGPD':''), docs:[{t:'desc',lab:'Descaracterização'},{t:'foto',lab:'Fotográfico'}], fotos:1},\n   {done:i>=4, ic:'🏅', tt:'CDF emitido e validado pelo RT', quando:'12/08/2026', onde:'Recicladora homologada CETESB', quem:'Eng. RT + destino homologado', oque:'Certificado de Destinação Final com QR verificável', docs:[{t:'mtrs',lab:'MTR saída'},{t:'cdf',lab:'CDF'}], fotos:1},\n  ];\n}\nfunction chainHTML(o){\n  return `<div class=\"cchain\">${chainFor(o).map(s=>`\n    <div class=\"cs ${s.done?'':'fut'}\"><div class=\"cn\">${s.ic}</div>\n      <div class=\"cc\"><h4>${s.tt} ${s.done?'<span class=\"pill p-ok\">concluído</span>':'<span class=\"pill\" style=\"background:#eef2f6;color:#64748b\">previsto</span>'}</h4>\n        <div class=\"meta\">🕒 <b>${s.quando}</b> · 📍 ${s.onde}<br>👤 ${s.quem} · 📦 ${s.oque}</div>\n        <div class=\"tags\">\n          ${(s.docs||[]).map(d=>`<span class=\"tagdoc ${docCls(d.t)}\" onclick=\"downloadDoc('${d.t}','${o.id}')\">📄 ${d.lab}</span>`).join('')}\n          ${s.fotos?`<span class=\"tagdoc\" style=\"background:#eafaef;color:#166534\" onclick=\"go('evidencias')\">📸 ${s.fotos} foto(s) geo</span>`:''}\n        </div></div></div>`).join('')}</div>`;\n}\n\n/* ---------- toast / modal ---------- */\nfunction toast(msg,ico='✓'){\n  const t=document.createElement('div');t.className='toast';t.innerHTML=`<span class=\"ck\">${ico}</span> ${esc(msg)}`;\n  $('#toasts').appendChild(t);setTimeout(()=>{t.style.opacity='0';t.style.transition='opacity .4s';setTimeout(()=>t.remove(),400);},2600);\n}\nfunction openModal(html){$('#modal').innerHTML=html;$('#overlay').classList.add('on');}\nfunction closeModal(){$('#overlay').classList.remove('on');}\n$('#overlay').addEventListener('click',e=>{if(e.target.id==='overlay')closeModal();});\n\n/* ---------- NAV ---------- */\nconst TITLES={painel:'Painel',kanban:'Acompanhamento em tempo real',rastreabilidade:'Rastreabilidade · cadeia de custódia',evidencias:'Evidências fotográficas georreferenciadas',docs:'Central de documentos',relatorios:'Relatórios',nova:'Nova solicitação de coleta',expressa:'Coleta Expressa',carbono:'Carbono & ESG',seguranca:'Segurança & Conformidade',adote:'Adote um Bairro',atendimento:'Atendimento',usuarios:'Usuários & acessos'};\nfunction go(nav){\n  document.querySelectorAll('.nav').forEach(b=>b.classList.toggle('active',b.dataset.nav===nav));\n  $('#title').textContent=TITLES[nav]||'Painel';\n  VIEWS[nav]();\n  $('#view').scrollTo?.(0,0); window.scrollTo(0,0);\n}\ndocument.querySelectorAll('.nav').forEach(b=>b.addEventListener('click',()=>go(b.dataset.nav)));\n\n/* ================= VIEWS ================= */\nconst VIEWS={};\n\nVIEWS.painel=()=>{\n  const done=OS.filter(o=>o.col==='concluido').length;\n  $('#view').innerHTML=`\n  <div class=\"grid k4\">\n    <div class=\"card kpi\"><div class=\"accent\"></div><div class=\"ic\">🚚</div><div class=\"lab\">Coletas no mês</div><div class=\"val mono\">12</div><div class=\"foot\">▲ 3 vs. mês anterior</div></div>\n    <div class=\"card kpi\"><div class=\"accent\"></div><div class=\"ic\">♻️</div><div class=\"lab\">Resíduos destinados</div><div class=\"val mono\">3.482 <small>kg</small></div><div class=\"foot\">100% com destino certificado</div></div>\n    <div class=\"card kpi\"><div class=\"accent\"></div><div class=\"ic\">🌍</div><div class=\"lab\">CO₂ evitado</div><div class=\"val mono\">5,1 <small>t</small></div><div class=\"foot\">Pronto p/ relatório ESG</div></div>\n    <div class=\"card kpi\"><div class=\"accent\"></div><div class=\"ic\">📄</div><div class=\"lab\">Documentos emitidos</div><div class=\"val mono\">148</div><div class=\"foot\">CDF · MTR · Laudos</div></div>\n  </div>\n  <div class=\"esg\">\n    <div style=\"font-size:26px\">♻️</div>\n    <div><div class=\"big\">Aterro zero: <span class=\"em\">100%</span> dos resíduos com destinação final certificada</div>\n    <div style=\"font-size:13px;color:#bfe6c8;margin-top:3px\">Cada quilo com rastreabilidade completa e documento verificável.</div></div>\n    <button class=\"badge\" onclick=\"downloadDoc('esg')\">📈 Baixar relatório ESG</button>\n  </div>\n  <div class=\"grid k3\" style=\"margin-top:16px\">\n    <div class=\"card pad\"><h3 class=\"blk\">Coletas — últimos 6 meses</h3>\n      <div class=\"sparkrow\">${[6,8,7,9,11,12].map(h=>`<div class=\"bar2\" style=\"height:${Math.round(h/12*100)}%\" title=\"${h}\"></div>`).join('')}</div>\n      <div class=\"mut\" style=\"font-size:11px;margin-top:6px;display:flex;justify-content:space-between\"><span>Mar</span><span>Abr</span><span>Mai</span><span>Jun</span><span>Jul</span><span>Ago</span></div></div>\n    <div class=\"card pad\" style=\"display:flex;align-items:center;gap:16px\"><div class=\"donut\"><div class=\"in\">100%</div></div>\n      <div><h3 class=\"blk\" style=\"margin:0 0 4px\">Destinação certificada</h3><p class=\"mut\" style=\"font-size:12.5px;margin:0;line-height:1.5\">Aterro zero — cada quilo com CDF e rastreabilidade.</p></div></div>\n    <div class=\"card pad\"><h3 class=\"blk\">Conformidade</h3>\n      ${['CONAMA','LGPD','ISO 14001','MTR · CDF'].map(x=>`<div style=\"display:flex;align-items:center;gap:8px;font-size:13px;color:var(--ink);margin:7px 0\"><span class=\"pill p-ok\">✓</span> ${x}</div>`).join('')}\n      <button class=\"btn-ghost\" style=\"margin-top:6px\" onclick=\"go('relatorios')\">Ver relatórios →</button></div>\n  </div>\n  <div class=\"grid k3\" style=\"margin-top:16px\">\n    <div class=\"card pad\"><h3 class=\"blk\">🔎 Rastreabilidade</h3><p class=\"mut\" style=\"font-size:13px;margin:0 0 14px\">Cadeia de custódia ponta a ponta — quem, quando, onde (GPS) e o quê.</p><button class=\"btn2\" onclick=\"go('rastreabilidade')\">Abrir →</button></div>\n    <div class=\"card pad\"><h3 class=\"blk\">📸 Evidências geo</h3><p class=\"mut\" style=\"font-size:13px;margin:0 0 14px\">Fotos com GPS, endereço e data/hora carimbados em cada etapa.</p><button class=\"btn2\" onclick=\"go('evidencias')\">Ver fotos →</button></div>\n    <div class=\"card pad\"><h3 class=\"blk\">➕ Nova coleta</h3><p class=\"mut\" style=\"font-size:13px;margin:0 0 14px\">Abra em 1 minuto — ou Coleta Expressa em 24h.</p><button class=\"btn2\" onclick=\"go('nova')\">Solicitar →</button> <button class=\"btn-ghost\" onclick=\"go('expressa')\">⚡</button></div>\n  </div>`;\n};\n\nVIEWS.kanban=(filter='todos')=>{\n  const cols=COLS.map(c=>{\n    const items=OS.filter(o=>o.col===c.k && (filter==='todos'|| (filter==='lgpd'? o.dados:true)));\n    return `<div class=\"col\"><h5>${c.t}<span class=\"n\">${items.length}</span></h5>\n      ${items.map(o=>card(o)).join('')||'<div class=\"mut\" style=\"font-size:11.5px;padding:6px\">—</div>'}</div>`;\n  }).join('');\n  $('#view').innerHTML=`\n   <div class=\"sechead\"><div class=\"hint\">Clique em qualquer cartão para ver a linha do tempo e baixar os documentos.</div>\n     <div class=\"spread\"></div>\n     <span class=\"chip ${filter==='todos'?'sel':''}\" onclick=\"VIEWS.kanban('todos')\">Todas</span>\n     <span class=\"chip ${filter==='lgpd'?'sel':''}\" onclick=\"VIEWS.kanban('lgpd')\">🔒 Com dados (LGPD)</span>\n   </div>\n   <div style=\"overflow-x:auto\"><div class=\"kan\" style=\"min-width:920px\">${cols}</div></div>`;\n};\nfunction card(o){\n  return `<button class=\"kc ${o._new?'new':''}\" onclick=\"openOS('${o.id}')\">\n    <div class=\"os\">${o.id}</div><div class=\"cli\">${esc(o.tipo)} · ${esc(o.qtd)}</div>\n    <div class=\"mt\"><span class=\"pill ${o.tag[0]}\">${esc(o.tag[1])}</span>${o.dados?' 🔒':''}</div></button>`;\n}\n\nwindow.openOS=(id, tab)=>{\n  const o=OS.find(x=>x.id===id); if(!o)return; tab=tab||'timeline';\n  const st=steps(o), ds=docsFor(o), fs=fotosFor(o);\n  const T=(k,l)=>`<button class=\"tab ${tab===k?'sel':''}\" onclick=\"openOS('${o.id}','${k}')\">${l}</button>`;\n  let body='';\n  if(tab==='timeline'){\n    body=`<div class=\"tl\">${st.map(s=>`\n       <div class=\"step ${s.real?'':'future'}\"><div class=\"nd\">${s.real?'✓':'•'}</div>\n         <div><div class=\"tt\">${esc(s.tt)} ${s.real?'<span class=\"b p-ok\">no prazo</span>':'<span class=\"b\" style=\"background:#eef2f6;color:#64748b\">previsto</span>'}</div>\n         <div class=\"dts\"><span>Previsto: ${s.prev}</span>${s.real?`<span class=\"rz\">Realizado: ${s.real}</span>`:''}</div></div></div>`).join('')}</div>\n     <div class=\"card pad\" style=\"background:#ecfdf3;border-color:#bbf7d0\">\n       <div style=\"font-weight:800;color:#166534;font-size:13px\">✅ No prazo · SLA 15 dias</div>\n       <div class=\"mut\" style=\"font-size:12px;margin-top:3px\">Responsável Técnico: Eng. Marcelo Aragão · CREA 5062654748</div></div>`;\n  } else if(tab==='docs'){\n    body= ds.length? `<div class=\"card rowlist\">${ds.map(d=>`\n       <div class=\"row\"><div class=\"ic\">${d.ic}</div><div><div class=\"nm\">${esc(d.nm)}</div><div class=\"meta\">${o.id} · validado pelo RT</div></div>\n         <button class=\"dl\" onclick=\"downloadDoc('${d.t}','${o.id}')\">⬇ Baixar</button></div>`).join('')}</div>`\n      : `<div class=\"hollow\">Os documentos ficam disponíveis conforme a coleta avança. Assim que o CDF for emitido e validado pelo RT, tudo aparece aqui.</div>`;\n  } else if(tab==='fotos'){\n    body= fs.length? `<div class=\"note\" style=\"margin:0 0 12px\">Cada foto carimbada com GPS, endereço, data/hora e responsável. Clique para ver no mapa.</div><div class=\"gallery\">${fs.map((p,idx)=>fotoCard(p,o.id,idx)).join('')}</div>`\n      : `<div class=\"hollow\">As fotos georreferenciadas aparecem assim que a coleta é realizada.</div>`;\n  } else {\n    body= `<div class=\"note\" style=\"margin:0 0 12px\">Cadeia de custódia auditável — quem, quando, onde (GPS), o quê e os documentos de cada etapa.</div>`+chainHTML(o);\n  }\n  openModal(`\n   <div class=\"mh\"><h3>${o.id} · ${esc(o.tipo)}</h3><span class=\"pill ${o.tag[0]}\">${esc(o.tag[1])}</span><button class=\"x\" onclick=\"closeModal()\">✕</button></div>\n   <div class=\"mb\">\n     <div class=\"tabs\">${T('timeline','Linha do tempo')}${T('docs','Documentos ('+ds.length+')')}${T('fotos','Fotos geo ('+fs.length+')')}${T('cadeia','Cadeia de custódia')}</div>\n     ${body}\n   </div>`);\n};\n\n/* ---------- documento (preview) ---------- */\nwindow.downloadDoc=(type,osId)=>{\n  const o=OS.find(x=>x.id===osId)||{id:'OS-2021',tipo:'Equip. de informática',qtd:'512 kg'};\n  let body='';\n  if(type==='cdf'){\n    body=`<div class=\"cert\"><div class=\"ch\"><img src=\"data:image/png;base64,\"><div class=\"t\"><b>Certificado de Destinação Final</b><span>Nº CDF-${o.id.replace('OS-','')} · ${o.id}</span></div></div>\n      <div class=\"cb\"><h4>Destinação ambientalmente correta</h4>\n        <div class=\"r\"><span>Gerador</span><b>Empresa Demonstração S.A.</b></div>\n        <div class=\"r\"><span>Resíduo</span><b>${esc(o.tipo)} · ${esc(o.qtd)}</b></div>\n        <div class=\"r\"><span>Destino</span><b>Recicladora homologada CETESB</b></div>\n        <div class=\"r\"><span>Tratamento</span><b>Descaracterização + reciclagem</b></div>\n        <div class=\"r\" style=\"border:none\"><span>Emissão</span><b>03/08/2026</b></div>\n        <div class=\"scan\"><img src=\"${QR}\" alt=\"QR\"></div>\n        <div class=\"stamp\">✓ AUTÊNTICO<small>Eng. M. Aragão · CREA 5062654748</small></div>\n      </div></div>`;\n  } else {\n    const map={mtr:['MTR de entrada','Manifesto de Transporte de Resíduos'],mtrs:['MTR de saída','Manifesto de Transporte de Resíduos'],\n      lgpd:['Laudo de Destruição de Dados (LGPD)','Comprova a destruição definitiva dos dados'],\n      desc:['Laudo de Descaracterização','Comprova a destruição física do material'],\n      foto:['Laudo Fotográfico','Registro fotográfico de cada etapa'],\n      esg:['Relatório de Carbono & ESG','CO₂ evitado no período · metodologia Villanova ESG']};\n    const m=map[type]||['Documento','Documento do sistema'];\n    body=`<div class=\"cert\"><div class=\"ch\"><img src=\"data:image/png;base64,\"><div class=\"t\"><b>${esc(m[0])}</b><span>${esc(o.id||'—')}</span></div></div>\n      <div class=\"cb\"><h4>${esc(m[0])}</h4><p class=\"mut\" style=\"font-size:13px;margin:0 0 8px\">${esc(m[1])}</p>\n        <div class=\"r\"><span>Gerador</span><b>Empresa Demonstração S.A.</b></div>\n        <div class=\"r\"><span>Referência</span><b>${esc(o.id||'—')} · ${esc(o.tipo||'')}</b></div>\n        <div class=\"r\" style=\"border:none\"><span>Responsável Técnico</span><b>Eng. Marcelo Aragão · CREA 5062654748</b></div>\n        <div class=\"stamp\">✓ Assinado pelo RT</div>\n      </div></div>`;\n  }\n  openModal(`<div class=\"mh\"><h3>Visualizar documento</h3><button class=\"x\" onclick=\"closeModal()\">✕</button></div>\n    <div class=\"mb\">${body}\n      <div style=\"display:flex;gap:10px;margin-top:16px;align-items:center\">\n        <button class=\"btn2\" onclick=\"toast('Download simulado — no sistema real, o PDF é baixado.','⬇')\">⬇ Baixar PDF</button>\n        <button class=\"btn-ghost\" onclick=\"toast('Link de verificação simulado.','🔗')\">🔗 Verificar autenticidade</button>\n        <span class=\"note\" style=\"margin:0 0 0 auto\">Demonstração — documento ilustrativo.</span>\n      </div></div>`);\n};\n\n/* pagamento: removido da demonstração — sem preço, sem bloqueio (ferramenta de marketing) */\n\nVIEWS.docs=(filter='todos')=>{\n  const all=[];\n  OS.forEach(o=>docsFor(o).forEach(d=>all.push({...d,os:o.id,tipo:o.tipo})));\n  all.push({t:'esg',nm:'Relatório de Carbono & ESG',ic:'📈',cls:'p-esg',lab:'ESG',os:'Consolidado',tipo:'CO₂ evitado do mês'});\n  const F={todos:()=>true,cdf:d=>d.lab==='CDF',mtr:d=>d.lab==='MTR',laudo:d=>d.lab==='LAUDO',esg:d=>d.lab==='ESG'};\n  const list=all.filter(F[filter]);\n  $('#view').innerHTML=`\n   <div class=\"sechead\"><div class=\"hint\">Filtre e baixe qualquer documento — pronto para auditoria.</div><div class=\"spread\"></div>\n     ${['todos|Todos','cdf|📑 CDF','mtr|🚚 MTR','laudo|🔒 Laudos','esg|📈 ESG'].map(x=>{const[k,l]=x.split('|');return `<span class=\"chip ${filter===k?'sel':''}\" onclick=\"VIEWS.docs('${k}')\">${l}</span>`;}).join('')}</div>\n   <div class=\"card rowlist\">${list.map(d=>`\n     <div class=\"row\"><div class=\"ic\">${d.ic}</div><div><div class=\"nm\">${esc(d.nm)}</div><div class=\"meta\">${esc(d.os)} · ${esc(d.tipo)}</div></div>\n       <span class=\"pill ${d.cls}\" style=\"margin-left:auto\">${d.lab}</span>\n       <button class=\"dl\" onclick=\"downloadDoc('${d.t}','${d.os}')\">⬇ Baixar</button></div>`).join('')}</div>\n   <div class=\"note\">✅ Compatível com auditorias <b>ISO 14001</b> · <b>CONAMA</b> · <b>LGPD</b></div>`;\n};\n\nVIEWS.nova=()=>{\n  $('#view').innerHTML=`\n   <div class=\"grid k2\" style=\"align-items:start\">\n     <div class=\"card pad form\">\n       <h3 class=\"blk\">➕ Abrir nova solicitação</h3>\n       <label>Tipo de resíduo</label>\n       <select id=\"f-tipo\"><option>Eletrônicos / informática</option><option>Notebooks</option><option>Servidores</option><option>HDs e mídias</option><option>Monitores</option><option>Outros</option></select>\n       <label>Quantidade estimada</label><input id=\"f-qtd\" value=\"250 kg\">\n       <label>Endereço de coleta</label><input id=\"f-end\" value=\"Matriz — São Paulo/SP\">\n       <label>Contém dados sensíveis? (LGPD)</label>\n       <select id=\"f-dados\"><option value=\"sim\">Sim — emitir laudo de destruição de dados</option><option value=\"nao\">Não</option></select>\n       <button class=\"btn2\" style=\"margin-top:18px;width:100%;padding:12px\" onclick=\"submitNova()\">Solicitar coleta</button>\n     </div>\n     <div class=\"card pad\">\n       <h3 class=\"blk\">Como funciona</h3>\n       <div class=\"tl\">\n         <div class=\"step\"><div class=\"nd\">1</div><div><div class=\"tt\">Você solicita em 1 minuto</div><div class=\"dts\">sem burocracia, direto no portal</div></div></div>\n         <div class=\"step\"><div class=\"nd\">2</div><div><div class=\"tt\">A Ecobraz agenda a coleta</div><div class=\"dts\">com prazo e SLA definidos</div></div></div>\n         <div class=\"step\"><div class=\"nd\">3</div><div><div class=\"tt\">Você acompanha em tempo real</div><div class=\"dts\">nos 5 estágios do Kanban</div></div></div>\n         <div class=\"step future\"><div class=\"nd\">4</div><div><div class=\"tt\">Recebe CDF + laudos</div><div class=\"dts\">tudo validado pelo RT</div></div></div>\n       </div>\n     </div>\n   </div>`;\n};\nwindow.submitNova=()=>{\n  const tipo=$('#f-tipo').value, qtd=$('#f-qtd').value, dados=$('#f-dados').value==='sim';\n  const id='OS-'+(seq++);\n  OS.unshift({id,tipo,qtd,col:'aguardando',tag:['p-warn','Agendando…'],valor:Math.round((900+Math.random()*2500)/10)*10,pago:false,dados,_new:true});\n  toast('Solicitação '+id+' registrada!');\n  go('kanban');\n  setTimeout(()=>{const o=OS.find(x=>x.id===id);if(o)o._new=false;},1200);\n};\n\nVIEWS.expressa=()=>{\n  $('#view').innerHTML=`\n   <div class=\"grid k2\" style=\"align-items:center\">\n     <div class=\"card pad\" style=\"border:2px solid var(--gold);text-align:center\">\n       <div style=\"font-size:44px\">⚡</div>\n       <h3 style=\"font-size:24px;color:var(--navy);margin:8px 0 4px\">Coleta Expressa em 24h</h3>\n       <p class=\"mut\" style=\"font-size:14px;margin:0 0 18px\">Para quando não dá para esperar.</p>\n       <button class=\"btn2\" style=\"padding:12px 22px;font-size:14px\" onclick=\"submitExpressa()\">Solicitar agora</button>\n     </div>\n     <div class=\"card pad\"><h3 class=\"blk\">Passo a passo</h3>\n       ${['Solicite pelo portal em 1 minuto','A Ecobraz confirma e agenda em 24h','Rastreie o transporte em tempo real','Receba CDF e laudos no portal'].map((t,i)=>`\n         <div class=\"tl\"><div class=\"step ${i===3?'future':''}\"><div class=\"nd\">${i+1}</div><div><div class=\"tt\">${t}</div></div></div></div>`).join('')}\n     </div>\n   </div>`;\n};\nwindow.submitExpressa=()=>{\n  const id='OS-'+(seq++);\n  OS.unshift({id,tipo:'Coleta Expressa (24h)',qtd:'—',col:'aguardando',tag:['p-warn','Expressa · 24h'],dados:false,_new:true});\n  toast('Coleta Expressa '+id+' solicitada — coleta em 24h.','⚡');\n  go('kanban');\n  setTimeout(()=>{const o=OS.find(x=>x.id===id);if(o)o._new=false;},1200);\n};\n\nVIEWS.carbono=()=>{\n  $('#view').innerHTML=`\n   <div class=\"grid\" style=\"grid-template-columns:300px 1fr;gap:18px;align-items:start\">\n     <div class=\"card pad\" style=\"background:linear-gradient(180deg,var(--forest),var(--forest2));color:#eafaef\">\n       <div style=\"font-size:12.5px;color:var(--green);font-weight:800\">CO₂ EVITADO ACUMULADO</div>\n       <div style=\"font-size:44px;font-weight:900;color:var(--green);line-height:1;margin-top:8px\">5,1 t</div>\n       <div style=\"font-size:12.5px;color:#bfe6c8;margin-top:4px\">no período — só com a sua destinação</div>\n       <div style=\"margin-top:18px;display:flex;flex-direction:column;gap:11px;font-size:13px;color:#cfe9d6\">\n         <div>🌳 equivale a <b style=\"color:#fff\">~240 árvores</b>/ano</div>\n         <div>🚗 ou <b style=\"color:#fff\">~21.000 km</b> não rodados</div>\n       </div>\n       <button class=\"btn2\" style=\"margin-top:18px;width:100%\" onclick=\"downloadDoc('esg')\">📈 Baixar relatório ESG</button>\n     </div>\n     <div class=\"card pad\"><h3 class=\"blk\">CO₂ evitado por material</h3>\n       ${[['Aço',90,'1,9 t'],['Alumínio',66,'1,4 t'],['Cobre',48,'1,0 t'],['Plástico',24,'0,5 t'],['Placas',14,'0,3 t']].map(b=>`\n         <div class=\"bar\"><div class=\"lb\">${b[0]}</div><div class=\"track\"><div class=\"fill\" style=\"width:0\" data-w=\"${b[1]}\"></div></div><div class=\"vl mono\">${b[2]}</div></div>`).join('')}\n       <div class=\"hollow\" style=\"margin-top:14px\">🔬 Metodologia <b>validada pela Villanova ESG</b> — auditável e pronta para o seu relatório de sustentabilidade.</div>\n     </div>\n   </div>`;\n  setTimeout(()=>document.querySelectorAll('#view .fill').forEach((f,i)=>setTimeout(()=>f.style.width=f.dataset.w+'%',i*120)),80);\n};\n\nVIEWS.seguranca=()=>{\n  const items=[['🏢','Acesso restrito por CNPJ','Cada empresa vê apenas os seus próprios dados e documentos.'],\n   ['👥','Níveis por usuário','Ver, baixar ou administrar — você controla o que cada pessoa acessa.'],\n   ['🔑','Login sem senha','Entrada por link seguro ou Google — nada de senha para vazar.'],\n   ['🔒','Conformidade LGPD','Laudo de destruição de dados e tratamento conforme a lei.'],\n   ['🧾','Trilha de auditoria','Cada documento com origem, data e responsável técnico.'],\n   ['☁️','Nuvem de alta confiança','Infraestrutura global, com backup e alta disponibilidade.']];\n  $('#view').innerHTML=`<div class=\"grid k3\">${items.map(i=>`\n    <div class=\"card pad\"><div style=\"width:46px;height:46px;border-radius:12px;background:#eafaef;display:flex;align-items:center;justify-content:center;font-size:22px\">${i[0]}</div>\n      <h3 class=\"blk\" style=\"margin:12px 0 5px\">${i[1]}</h3><p class=\"mut\" style=\"font-size:12.5px;margin:0;line-height:1.5\">${i[2]}</p></div>`).join('')}</div>`;\n};\n\nVIEWS.adote=()=>{\n  $('#view').innerHTML=`\n   <div class=\"grid\" style=\"grid-template-columns:1fr 300px;gap:18px;align-items:start\">\n     <div class=\"card pad\" style=\"background:linear-gradient(135deg,var(--forest),#12503a);color:#eafaef\">\n       <div style=\"color:var(--green);font-size:13px;font-weight:800\">◆ PROPÓSITO COM LASTRO</div>\n       <h3 style=\"font-size:26px;font-weight:900;margin:8px 0\">Sua marca ligada a impacto real</h3>\n       <p style=\"font-size:13.5px;color:#cfe9d6;line-height:1.55;max-width:560px\">Você adota um bairro e patrocina a coleta de lixo eletrônico que quase ninguém faz — a \"última milha\". Recebe a documentação auditável de tudo, e cada coleta patrocinada baixa o seu termômetro de CO₂.</p>\n       <div class=\"grid k3\" style=\"gap:12px;margin-top:16px\">\n         <div style=\"background:rgba(122,201,67,.12);border:1px solid rgba(122,201,67,.3);border-radius:12px;padding:12px;text-align:center\"><div style=\"font-size:24px;font-weight:900;color:var(--green)\">1–10 t</div><div style=\"font-size:10.5px;color:#bfe6c8\">módulos/ano</div></div>\n         <div style=\"background:rgba(122,201,67,.12);border:1px solid rgba(122,201,67,.3);border-radius:12px;padding:12px;text-align:center\"><div style=\"font-size:24px;font-weight:900;color:var(--green)\">100%</div><div style=\"font-size:10.5px;color:#bfe6c8\">documentado</div></div>\n         <div style=\"background:rgba(122,201,67,.12);border:1px solid rgba(122,201,67,.3);border-radius:12px;padding:12px;text-align:center\"><div style=\"font-size:24px;font-weight:900;color:var(--green)\">↓ CO₂</div><div style=\"font-size:10.5px;color:#bfe6c8\">termômetro</div></div>\n       </div>\n       <button class=\"btn2\" style=\"margin-top:18px\" onclick=\"toast('Interesse registrado — nossa equipe entra em contato (demo).','🤝')\">Quero patrocinar</button>\n     </div>\n     <div style=\"display:flex;flex-direction:column;gap:11px\">\n       ${[['🌱','Impacto ESG de verdade','Cada tonelada financia a coleta correta em comunidades.'],['🏅','Com lastro e prova','Documentação auditável de cada coleta.'],['❤️','Marca admirada','Impacto social real, no nome da sua empresa.']].map(b=>`\n         <div class=\"card pad\" style=\"display:flex;gap:12px;align-items:flex-start\"><div style=\"font-size:20px\">${b[0]}</div><div><div style=\"font-weight:800;color:var(--navy);font-size:13px\">${b[1]}</div><div class=\"mut\" style=\"font-size:11.5px;margin-top:2px\">${b[2]}</div></div></div>`).join('')}\n     </div>\n   </div>`;\n};\n\nVIEWS.atendimento=()=>{\n  $('#view').innerHTML=`\n   <div class=\"grid k2\" style=\"align-items:center\">\n     <div class=\"card pad\">\n       <h3 class=\"blk\">Atendimento humano, de verdade</h3>\n       ${[['💬','Sem robô, sem fila','Gente que conhece o seu caso.'],['📱','WhatsApp a um clique','Comercial e suporte direto do portal.'],['⚡','Resposta rápida','Dúvida, urgência ou orçamento.']].map(b=>`\n         <div style=\"display:flex;gap:12px;align-items:flex-start;margin-bottom:14px\"><div style=\"width:42px;height:42px;border-radius:11px;background:#eafaef;display:flex;align-items:center;justify-content:center;font-size:20px\">${b[0]}</div><div><div style=\"font-weight:800;color:var(--navy);font-size:14px\">${b[1]}</div><div class=\"mut\" style=\"font-size:12.5px\">${b[2]}</div></div></div>`).join('')}\n       <button class=\"btn2\" onclick=\"toast('Abrindo WhatsApp… (demo)','💬')\">Falar no WhatsApp</button>\n     </div>\n     <div class=\"card pad\" style=\"background:#ded5cb\">\n       <div style=\"background:#fff;border-radius:12px;padding:9px 12px;font-size:13px;max-width:85%;margin-bottom:10px;box-shadow:0 1px 2px rgba(0,0,0,.1)\">Oi! Preciso agendar a coleta de 200 notebooks. Como faço?</div>\n       <div style=\"background:#dcf8c6;border-radius:12px;padding:9px 12px;font-size:13px;max-width:85%;margin:0 0 10px auto;box-shadow:0 1px 2px rgba(0,0,0,.1)\">Olá! Dá pra abrir no portal em 1 minuto — ou eu abro pra você agora 😊</div>\n       <div style=\"background:#fff;border-radius:12px;padding:9px 12px;font-size:13px;max-width:85%;margin-bottom:10px;box-shadow:0 1px 2px rgba(0,0,0,.1)\">E os laudos de LGPD, vocês emitem?</div>\n       <div style=\"background:#dcf8c6;border-radius:12px;padding:9px 12px;font-size:13px;max-width:85%;margin-left:auto;box-shadow:0 1px 2px rgba(0,0,0,.1)\">Sim! Laudo assinado pelo nosso engenheiro — fica tudo no seu portal ✅</div>\n     </div>\n   </div>`;\n};\n\nVIEWS.usuarios=()=>{\n  const u=[['PS','Diretor','Visão executiva + gestão de usuários','ADMIN','p-cdf'],\n   ['EC','Engenheiro Clínico','Acompanha e baixa laudos técnicos','VER + BAIXAR','p-ok'],\n   ['GA','Gestor Ambiental','Acompanha o andamento das coletas','VER','p-doc']];\n  $('#view').innerHTML=`\n   <div class=\"sechead\"><div class=\"hint\">Cada empresa gerencia seus próprios usuários, com níveis de acesso.</div>\n     <button class=\"btn2 spread\" onclick=\"toast('Convite enviado (demo).','✉️')\">＋ Convidar usuário</button></div>\n   <div class=\"card rowlist\">${u.map(x=>`\n     <div class=\"row\"><div class=\"avatar\">${x[0]}</div><div><div class=\"nm\">${x[1]}</div><div class=\"meta\">${x[2]}</div></div>\n       <span class=\"pill ${x[4]}\" style=\"margin-left:auto\">${x[3]}</span></div>`).join('')}</div>\n   <div class=\"note\">🔒 Acesso restrito por CNPJ — ninguém de fora da sua empresa vê seus dados.</div>`;\n};\n\n/* ---------- RASTREABILIDADE ---------- */\nVIEWS.rastreabilidade=(id)=>{\n  const o=OS.find(x=>x.id===id) || OS.find(x=>x.col==='concluido') || OS[0];\n  const chips=OS.map(x=>`<span class=\"chip ${x.id===o.id?'sel':''}\" onclick=\"VIEWS.rastreabilidade('${x.id}')\">${x.id}</span>`).join('');\n  $('#view').innerHTML=`\n   <div class=\"sechead\"><div class=\"hint\">Cadeia de custódia auditável: cada etapa com <b>quem</b>, <b>quando</b>, <b>onde (GPS)</b>, <b>o quê</b> e os <b>documentos</b>.</div></div>\n   <div style=\"display:flex;gap:8px;flex-wrap:wrap;margin-bottom:16px;overflow-x:auto\">${chips}</div>\n   <div class=\"card pad\">\n     <div style=\"display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin-bottom:10px\">\n       <h3 class=\"blk\" style=\"margin:0\">${o.id} · ${esc(o.tipo)} · ${esc(o.qtd)}</h3>\n       <span class=\"pill ${o.tag[0]}\">${esc(o.tag[1])}</span>\n       <button class=\"btn2\" style=\"margin-left:auto\" onclick=\"downloadDoc('rastr','${o.id}')\">📄 Relatório de rastreabilidade</button>\n     </div>\n     ${chainHTML(o)}\n   </div>`;\n};\n\n/* ---------- EVIDÊNCIAS (fotos geo) ---------- */\nVIEWS.evidencias=(id)=>{\n  const withF=OS.filter(x=>fotosFor(x).length);\n  const o=(id&&OS.find(x=>x.id===id&&fotosFor(x).length)) || withF[withF.length-1] || null;\n  const fs=o?fotosFor(o):[];\n  const chips=withF.map(x=>`<span class=\"chip ${o&&x.id===o.id?'sel':''}\" onclick=\"VIEWS.evidencias('${x.id}')\">${x.id}</span>`).join('');\n  $('#view').innerHTML=`\n   <div class=\"sechead\"><div class=\"hint\">Cada foto sai do campo com <b>GPS, endereço, data/hora e responsável</b> carimbados — prova visual à prova de contestação. Clique para ver no mapa.</div></div>\n   ${withF.length?`<div style=\"display:flex;gap:8px;flex-wrap:wrap;margin-bottom:16px\">${chips}</div>`:''}\n   ${fs.length? `<div class=\"gallery\">${fs.map((p,idx)=>fotoCard(p,o.id,idx)).join('')}</div>`\n     : `<div class=\"hollow\">As fotos aparecem assim que a coleta é realizada. Abra uma OS já em andamento.</div>`}`;\n};\n\n/* ---------- RELATÓRIOS ---------- */\nVIEWS.relatorios=()=>{\n  const R=[\n   ['esg','🌍','Relatório de Carbono & ESG','CO₂ evitado por material, com metodologia validada pela Villanova ESG.','p-esg'],\n   ['dmr','📋','DMR — Movimentação de Resíduos','Totais por tipo e destino no período. Base legal.','p-doc'],\n   ['conf','✅','Relatório de Conformidade','CONAMA · LGPD · ISO 14001 — status e evidências.','p-ok'],\n   ['destino','♻️','Relatório de Destinação','Materiais, % reciclado e destino homologado.','p-ok'],\n   ['foto','📸','Relatório Fotográfico','Compilado das evidências georreferenciadas.','p-cdf'],\n   ['rastr','🔎','Relatório de Rastreabilidade','Cadeia de custódia completa, ponta a ponta.','p-doc'],\n  ];\n  $('#view').innerHTML=`\n   <div class=\"sechead\"><div class=\"hint\">Relatórios prontos para auditoria — gere, visualize e baixe quando quiser.</div></div>\n   <div class=\"grid k3\">${R.map(r=>`\n     <div class=\"card pad\"><div style=\"display:flex;align-items:center;gap:10px\"><div style=\"width:42px;height:42px;border-radius:11px;background:#eafaef;display:flex;align-items:center;justify-content:center;font-size:20px\">${r[1]}</div><span class=\"pill ${r[4]}\">${r[0].toUpperCase()}</span></div>\n       <h3 class=\"blk\" style=\"margin:12px 0 5px\">${r[2]}</h3>\n       <p class=\"mut\" style=\"font-size:12.5px;margin:0 0 14px;line-height:1.5\">${r[3]}</p>\n       <button class=\"btn2\" onclick=\"openReport('${r[0]}')\">Abrir relatório</button></div>`).join('')}</div>\n   <div class=\"note\">✅ Metodologia auditável · exportável em PDF · compatível com ISO 14001, CONAMA e LGPD.</div>`;\n};\nwindow.openReport=(type)=>{\n  const per='Agosto/2026 · Empresa Demonstração S.A.';\n  const T={esg:'Relatório de Carbono & ESG',dmr:'DMR — Declaração de Movimentação de Resíduos',conf:'Relatório de Conformidade',destino:'Relatório de Destinação',foto:'Relatório Fotográfico',rastr:'Relatório de Rastreabilidade'}[type]||'Relatório';\n  let b='';\n  if(type==='esg'){\n    b=`<div class=\"repkpi\">\n      <div class=\"c\"><div class=\"n\">5,1 t</div><div class=\"l\">CO₂ evitado</div></div>\n      <div class=\"c\"><div class=\"n\">3.482 kg</div><div class=\"l\">resíduos destinados</div></div>\n      <div class=\"c\"><div class=\"n\">~240</div><div class=\"l\">árvores/ano equiv.</div></div>\n      <div class=\"c\"><div class=\"n\">~21 mil</div><div class=\"l\">km não rodados</div></div></div>\n     <table class=\"tbl\"><thead><tr><th>Material</th><th class=\"r\">CO₂ evitado</th><th style=\"width:40%\">Participação</th></tr></thead><tbody>\n      ${[['Aço','1,9 t',90],['Alumínio','1,4 t',66],['Cobre','1,0 t',48],['Plástico','0,5 t',24],['Placas eletrônicas','0,3 t',14]].map(m=>`<tr><td>${m[0]}</td><td class=\"r\">${m[1]}</td><td><div style=\"height:12px;background:#eef3f1;border-radius:6px;overflow:hidden\"><div style=\"height:100%;width:${m[2]}%;background:linear-gradient(90deg,var(--green),var(--emerald))\"></div></div></td></tr>`).join('')}\n     </tbody></table>\n     <div class=\"hollow\" style=\"margin-top:14px\">🔬 Metodologia <b>validada pela Villanova ESG</b> — auditável e pronta para o seu relatório de sustentabilidade.</div>`;\n  } else if(type==='dmr'){\n    b=`<table class=\"tbl\"><thead><tr><th>Tipo de resíduo</th><th class=\"r\">Qtd (kg)</th><th>Destino</th><th>Situação</th></tr></thead><tbody>\n      ${[['Equip. de informática','1.860','Recicladora homologada CETESB','Concluído'],['HDs e mídias','420','Trituração + reciclagem','Concluído'],['Monitores / CPUs','780','Descaracterização + reciclagem','Em processo'],['Placas eletrônicas','422','Recuperação de metais','Concluído']].map(r=>`<tr><td>${r[0]}</td><td class=\"r\">${r[1]}</td><td>${r[2]}</td><td><span class=\"pill ${r[3]==='Concluído'?'p-ok':'p-warn'}\">${r[3]}</span></td></tr>`).join('')}\n      <tr><td><b>Total</b></td><td class=\"r\"><b>3.482</b></td><td colspan=\"2\" class=\"mut\">100% com destino certificado</td></tr>\n     </tbody></table>`;\n  } else if(type==='conf'){\n    b=`<table class=\"tbl\"><thead><tr><th>Requisito</th><th>Evidência</th><th>Status</th></tr></thead><tbody>\n      ${[['Licenciamento ambiental do destino (CONAMA)','Licença CETESB do destino'],['Destruição de dados (LGPD)','Laudo assinado pelo RT'],['MTR emitidos (entrada/saída)','Manifestos rastreados'],['CDF validado por Responsável Técnico','CREA 5062654748 + QR'],['Gestão ambiental (ISO 14001)','Processos documentados']].map(r=>`<tr><td>${r[0]}</td><td class=\"mut\">${r[1]}</td><td><span class=\"pill p-ok\">✓ Conforme</span></td></tr>`).join('')}\n     </tbody></table><div class=\"note\">Todos os itens auditáveis, com documento e responsável rastreável.</div>`;\n  } else if(type==='destino'){\n    b=`<table class=\"tbl\"><thead><tr><th>Material</th><th class=\"r\">Peso (kg)</th><th class=\"r\">% reciclado</th><th>Destino</th></tr></thead><tbody>\n      ${[['Aço','1.120','98%','Siderúrgica homologada'],['Alumínio','610','97%','Recicladora homologada'],['Cobre','280','99%','Refino homologado'],['Plástico','840','86%','Reciclador homologado'],['Placas eletrônicas','632','94%','Recuperação de metais']].map(r=>`<tr><td>${r[0]}</td><td class=\"r\">${r[1]}</td><td class=\"r\">${r[2]}</td><td>${r[3]}</td></tr>`).join('')}\n      <tr><td><b>Total</b></td><td class=\"r\"><b>3.482</b></td><td class=\"r\"><b>~95%</b></td><td class=\"mut\">aterro zero</td></tr>\n     </tbody></table>`;\n  } else if(type==='foto'){\n    const o=OS.find(x=>x.col==='concluido')||OS[OS.length-1]; const fs=fotosFor(o);\n    b=`<div class=\"note\" style=\"margin:0 0 12px\">Evidências georreferenciadas de ${o.id}. Clique para ver metadados e mapa.</div>\n       <div class=\"gallery\">${fs.map((p,idx)=>fotoCard(p,o.id,idx)).join('')}</div>`;\n  } else {\n    const o=OS.find(x=>x.col==='concluido')||OS[OS.length-1];\n    b=chainHTML(o);\n  }\n  openModal(`<div class=\"mh\"><h3>${T}</h3><button class=\"x\" onclick=\"closeModal()\">✕</button></div>\n   <div class=\"mb\"><div class=\"report\"><div class=\"rh\"><img src=\"data:image/png;base64,\"><div><b style=\"font-size:14px\">${T}</b><div style=\"font-size:11px;color:#bfe6c8\">${per}</div></div><div class=\"t\">Ecobraz<br>Emitido em 12/08/2026</div></div>\n     <div class=\"rb\">${b}</div></div>\n     <div style=\"display:flex;gap:10px;margin-top:14px;align-items:center\"><button class=\"btn2\" onclick=\"toast('Relatório em PDF baixado (demo).','⬇')\">⬇ Baixar PDF</button>\n       <button class=\"btn-ghost\" onclick=\"toast('Relatório enviado por e-mail (demo).','✉️')\">Enviar por e-mail</button>\n       <span class=\"note\" style=\"margin:0 0 0 auto\">Demonstração — dados ilustrativos.</span></div>\n   </div>`);\n};\n\n/* ---------- boot ---------- */\n$('#enter').addEventListener('click',()=>{\n  $('#login').style.display='none';\n  $('#app').classList.add('on');\n  go('painel');\n});\n$('#reset').addEventListener('click',()=>{OS=seed();seq=2050;go('painel');toast('Demonstração reiniciada.','↺');});\ndocument.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();});\n</script>\n</body>\n</html>\n";
